'use strict';

var xorshift32 = require( './../lib' );

// Create a PRNG and capture its state...
var seed = 3141;
var rng = xorshift32.factory({
	'seed': seed
});

console.log( '\nInitial state:' );
console.log( rng.state );

// Generate some random numbers...
console.log( '\nGenerating 5 random numbers:' );
var i;
for ( i = 0; i < 5; i++ ) {
	console.log( rng() );
}

// Capture the state at this point...
var state = rng.state;
console.log( '\nState after 5 generations:' );
console.log( state );

// Generate more numbers...
console.log( '\nGenerating 5 more random numbers:' );
var sequence1 = [];
for ( i = 0; i < 5; i++ ) {
	sequence1.push( rng() );
	console.log( sequence1[ i ] );
}

// Restore the state and regenerate the same sequence...
rng.state = state;
console.log( '\nRestored state and regenerating sequence:' );
var sequence2 = [];
for ( i = 0; i < 5; i++ ) {
	sequence2.push( rng() );
	console.log( sequence2[ i ] );
}

// Verify sequences match...
console.log( '\nSequences match:', JSON.stringify( sequence1 ) === JSON.stringify( sequence2 ) );

// Demonstrate state with different options...
console.log( '\n\nUsing factory with state copy:' );
var state1 = xorshift32.state;
var rng1 = xorshift32.factory({
	'state': state1,
	'copy': true  // Creates independent copy of state
});
var rng2 = xorshift32.factory({
	'state': state1,
	'copy': false // Shares state reference
});

console.log( '\nrng1 (copy=true):', rng1() );
console.log( 'rng2 (copy=false):', rng2() );
console.log( 'Are they the same value?', rng1() === rng2() );
